/* ===================== BÀI 5 · A, B, R0–R7 và PSW ===================== */
/* Bài 5 · A, B, R0–R7 và PSW (AMTS-EMB-001-M02-L01, MC51-005) — sinh bởi tools/author/mcu8051/l05.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR5=[{"label":"Ví dụ: A, B, R0–R7 trước và sau từng lệnh","code":"; Ví dụ 1: chép dữ liệu qua A, B, R0-R7\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     A,#25H                  ; A = 25H\n        MOV     B,A                     ; B = 25H\n        MOV     R0,A                    ; R0 (ô 00H) = 25H\n        MOV     R7,#0F0H                ; R7 (ô 07H) = F0H\n        MOV     A,R7                    ; A = F0H\n        MOV     30H,R0                  ; ô 30H = 25H\n        SJMP    $\n        END\n","note":"Bấm Từng bước và ghi giá trị A, B, R0, R7 trước và sau mỗi lệnh. MOV R0,A chỉ 1 byte (F8) vì số thanh ghi nằm trong mã lệnh; MOV B,A dài 2 byte vì B là địa chỉ F0H. Tổng 7 chu kỳ máy tới SJMP $.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Cùng tên R0, bốn ô RAM theo băng","code":"; Ví dụ 2: cùng tên R0, bốn ô RAM khác nhau\n; RS1 RS0 trong PSW chọn băng thanh ghi.\n        ORG     0000H\n        MOV     R0,#11H                 ; băng 0: R0 là ô 00H\n        MOV     PSW,#08H                ; RS1 RS0 = 01: băng 1\n        MOV     R0,#22H                 ; R0 là ô 08H\n        MOV     PSW,#10H                ; RS1 RS0 = 10: băng 2\n        MOV     R0,#33H                 ; R0 là ô 10H\n        MOV     PSW,#18H                ; RS1 RS0 = 11: băng 3\n        MOV     R0,#44H                 ; R0 là ô 18H\n        MOV     PSW,#00H                ; về băng 0\n        MOV     A,R0                    ; A = ?\n        SJMP    $\n        END\n","note":"Mỗi lần ghi PSW, R0 trỏ sang ô khác: 00H, 08H, 10H, 18H (xem phần Bộ nhớ). Đoán trước: dòng cuối MOV A,R0 cho A bằng bao nhiêu? (11H, vì đã về băng 0.)","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Cờ CY, AC, OV và P sau phép cộng","code":"; Ví dụ 3: cờ CY, AC, OV, P sau phép cộng\n; MOV dir,PSW chụp cả byte PSW vào RAM để so.\n        ORG     0000H\n        MOV     A,#7AH\n        ADD     A,#86H                  ; 7AH + 86H = 100H\n        MOV     30H,PSW                 ; chụp PSW lần 1\n        MOV     A,#45H\n        ADD     A,#3EH                  ; 45H + 3EH = 83H\n        MOV     31H,PSW                 ; chụp PSW lần 2\n        SJMP    $\n        END\n","note":"Sau lệnh ADD đầu: A = 00H, CY = 1, AC = 1, OV = 0, P = 0, nên ô 30H = C0H. Sau lệnh ADD thứ hai: A = 83H, CY = 0, AC = 1, OV = 1, P = 1, nên ô 31H = 45H. Đối chiếu từng bit với bảng PSW.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Thanh ghi B trong DIV AB và MUL AB","code":"; Ví dụ 4: thanh ghi B trong DIV AB và MUL AB\n        ORG     0000H\n        MOV     A,#200                  ; A = 200 = C8H\n        MOV     B,#7                    ; B = 7\n        DIV     AB                      ; A = thương, B = số dư\n        MOV     R2,B                    ; cất số dư vào R2\n        MOV     B,#0AH                  ; B = 10\n        MUL     AB                      ; B:A = A x B\n        SJMP    $\n        END\n","note":"DIV AB: 200 : 7 = 28 dư 4, nên A = 1CH, B = 04H (4 chu kỳ). MUL AB: 1CH × 0AH = 0118H, nên A = 18H, B = 01H và OV = 1 vì tích lớn hơn FFH.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Đổi băng bằng SETB RS0, CLR RS0","code":"; Ví dụ 5: đổi băng bằng lệnh bit SETB/CLR RS0, RS1\n        ORG     0000H\n        MOV     R7,#0AH                 ; băng 0: R7 là ô 07H\n        SETB    RS0                     ; RS1 RS0 = 01: băng 1\n        MOV     R7,#0BH                 ; R7 là ô 0FH\n        SETB    RS1                     ; RS1 RS0 = 11: băng 3\n        MOV     R7,#0CH                 ; R7 là ô 1FH\n        CLR     RS0                     ; RS1 RS0 = 10: băng 2\n        MOV     R7,#0DH                 ; R7 là ô 17H\n        MOV     A,0FH                   ; đọc R7 của băng 1 qua địa chỉ\n        SJMP    $\n        END\n","note":"Mỗi lệnh SETB/CLR RS0, RS1 chỉ 2 byte, 1 chu kỳ, đổi băng mà giữ các cờ khác. Cuối cùng R7 (băng 2) là ô 17H, còn MOV A,0FH đọc R7 của băng 1 bằng địa chỉ: A = 0BH.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: PUSH ghi đè R0 của băng 1","code":"; Bẫy: sau reset SP = 07H, PUSH đầu tiên ghi vào ô 08H,\n; chính là R0 của băng 1.\n        ORG     0000H\n        MOV     PSW,#08H                ; băng 1\n        MOV     R0,#55H                 ; R0 băng 1 (ô 08H) = 55H\n        MOV     PSW,#00H                ; về băng 0\n        MOV     A,#0AAH\n        PUSH    ACC                     ; SP = 08H, ghi AAH vào ô 08H\n        MOV     PSW,#08H                ; sang băng 1 lần nữa\n        MOV     A,R0                    ; A = ?\n        SJMP    $\n        END\n","note":"Sau reset SP = 07H. PUSH ACC tăng SP lên 08H rồi ghi AAH vào ô 08H, đè lên R0 của băng 1 đã ghi 55H. Đoán trước: A cuối bằng bao nhiêu? (AAH.)","dev":{"led":true},"fosc":12000000}];
const sim5=makeSim51(document.getElementById("m51-l5"),{id:"s5",presets:PR5,ram:256});
makeEx51(document.getElementById("ex-l5"),"l5",[{"t":"Chép vào băng 2","d":"<p>Chép 4 byte ở <code>30H<\/code>–<code>33H<\/code> vào <code>R0<\/code>–<code>R3<\/code> của <b>băng 2<\/b> theo đúng thứ tự (R0 ← 30H, …, R3 ← 33H). R0–R3 của băng 0 (ô <code>00H<\/code>–<code>03H<\/code>) và các ô nguồn phải giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H..33H = 11H 22H 33H 44H<\/code> → R0–R3 của băng 2 = <code>11H 22H 33H 44H<\/code>.<\/p>","start":"        ORG     0000H\n; Chép 30H..33H vào R0..R3 của băng 2\n        MOV     R0,30H                  ; R0 này là của băng nào?\n        MOV     R1,31H\n        MOV     R2,32H\n        MOV     R3,33H\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":17,"0x31":34,"0x32":51,"0x33":68,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x10":238,"0x11":238,"0x12":238,"0x13":238}},"expect":{"iram":{"0x10":17,"0x11":34,"0x12":51,"0x13":68,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x30":17,"0x31":34,"0x32":51,"0x33":68}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x10":238,"0x11":238,"0x12":238,"0x13":238}},"expect":{"iram":{"0x10":0,"0x11":0,"0x12":0,"0x13":0,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x30":0,"0x31":0,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x10":238,"0x11":238,"0x12":238,"0x13":238}},"expect":{"iram":{"0x10":255,"0x11":255,"0x12":255,"0x13":255,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x30":255,"0x31":255,"0x32":255,"0x33":255}}},{"setup":{"iram":{"0x30":160,"0x31":161,"0x32":162,"0x33":163,"0x00":255,"0x01":254,"0x02":253,"0x03":252,"0x10":238,"0x11":238,"0x12":238,"0x13":238}},"expect":{"iram":{"0x10":160,"0x11":161,"0x12":162,"0x13":163,"0x00":255,"0x01":254,"0x02":253,"0x03":252,"0x30":160,"0x31":161,"0x32":162,"0x33":163}}},{"setup":{"iram":{"0x30":90,"0x31":0,"0x32":255,"0x33":128,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x10":238,"0x11":238,"0x12":238,"0x13":238}},"expect":{"iram":{"0x10":90,"0x11":0,"0x12":255,"0x13":128,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x30":90,"0x31":0,"0x32":255,"0x33":128}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":4,"0x33":8,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x10":238,"0x11":238,"0x12":238,"0x13":238}},"expect":{"iram":{"0x10":1,"0x11":2,"0x12":4,"0x13":8,"0x00":160,"0x01":161,"0x02":162,"0x03":163,"0x30":1,"0x31":2,"0x32":4,"0x33":8}}}]},"hints":["Băng 2 nằm ở các ô nào của RAM trong? Địa chỉ của Rn = 8 × số băng + n.","Code mẫu ghi đúng thứ tự nhưng vào băng nào? Sau reset RS1 RS0 = 00.","Thanh ghi nào chứa hai bit chọn băng? Đặt chúng đúng giá trị trước bốn lệnh chép."],"why":"Tên R0–R7 không cố định một ô nhớ: RS1 RS0 trong PSW chọn băng. Sau reset là băng 0, nên phải chọn băng 2 (MOV PSW,#10H) trước khi ghi; nếu không, dữ liệu rơi vào ô 00H–03H. Bộ thử đặt sẵn giá trị ở 00H–03H để bắt lỗi này."},{"t":"Cộng và ghi cờ","d":"<p>Cộng hai byte ở <code>30H<\/code> và <code>31H<\/code>. Ghi tổng 8 bit vào <code>32H<\/code>, ghi cờ <b>CY<\/b> của phép cộng vào <code>33H<\/code> và cờ <b>OV<\/b> vào <code>34H<\/code> (mỗi ô là <code>00H<\/code> hoặc <code>01H<\/code>). Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 7FH<\/code>, <code>31H = 01H<\/code> → <code>32H = 80H<\/code>, <code>33H = 00H<\/code> (không nhớ), <code>34H = 01H<\/code> (tràn có dấu).<\/p>","start":"        ORG     0000H\n        MOV     A,30H\n        ADD     A,31H\n        MOV     32H,A                   ; tổng 8 bit\n; Viết code ghi CY vào 33H và OV vào 34H\n        MOV     33H,#00H\n        MOV     34H,#00H\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":127,"0x31":1,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x32":128,"0x33":0,"0x34":1}}},{"setup":{"iram":{"0x30":255,"0x31":1,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x32":0,"0x33":1,"0x34":0}}},{"setup":{"iram":{"0x30":128,"0x31":128,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x32":0,"0x33":1,"0x34":1}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x32":0,"0x33":0,"0x34":0}}},{"setup":{"iram":{"0x30":18,"0x31":52,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x32":70,"0x33":0,"0x34":0}}},{"setup":{"iram":{"0x30":200,"0x31":100,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x32":44,"0x33":1,"0x34":0}}},{"setup":{"iram":{"0x30":80,"0x31":80,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x32":160,"0x33":0,"0x34":1}}}]},"hints":["Đọc PSW ngay sau ADD, trước khi một lệnh khác làm đổi cờ. MOV A,PSW chép cả byte cờ vào A.","CY là bit 7 của PSW, OV là bit 2. Xoay A để đưa bit cần lấy về bit 0, rồi ANL A,#01H xóa các bit khác.","Lấy CY và OV từ cùng một bản sao PSW, cất bản sao ở một thanh ghi: đọc PSW lần hai thì cờ đã đổi."],"why":"CY báo nhớ ra khỏi bit 7 (cộng không dấu vượt FFH), OV báo tràn có dấu (cộng hai số cùng dấu ra kết quả khác dấu). Hai cờ độc lập: 7FH + 01H có OV = 1, CY = 0; FFH + 01H có CY = 1, OV = 0; 80H + 80H có cả hai bằng 1."},{"t":"Cộng 8 byte trong 15 byte mã","d":"<p>Tám ô <code>08H<\/code>–<code>0FH<\/code> chứa 8 byte. Ghi tổng 8 bit của chúng (bỏ phần nhớ) vào <code>30H<\/code>. Các ô <code>00H<\/code>–<code>0FH<\/code> phải giữ nguyên. Code mẫu đã cho kết quả đúng nhưng dài 20 byte. Hãy viết lại để mã dài không quá <b>15 byte<\/b> và chạy không quá <b>13 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>).<\/p><p>Ví dụ: <code>08H..0FH = 01H 02H … 08H<\/code> → <code>30H = 24H<\/code>.<\/p>","start":"        ORG     0000H\n; Đúng kết quả nhưng dài 20 byte\n        MOV     A,08H\n        ADD     A,09H\n        ADD     A,0AH\n        ADD     A,0BH\n        ADD     A,0CH\n        ADD     A,0DH\n        ADD     A,0EH\n        ADD     A,0FH\n        MOV     30H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x08":1,"0x09":2,"0x0A":3,"0x0B":4,"0x0C":5,"0x0D":6,"0x0E":7,"0x0F":8,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":238}},"expect":{"iram":{"0x08":1,"0x09":2,"0x0A":3,"0x0B":4,"0x0C":5,"0x0D":6,"0x0E":7,"0x0F":8,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":36}}},{"setup":{"iram":{"0x08":0,"0x09":0,"0x0A":0,"0x0B":0,"0x0C":0,"0x0D":0,"0x0E":0,"0x0F":0,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":238}},"expect":{"iram":{"0x08":0,"0x09":0,"0x0A":0,"0x0B":0,"0x0C":0,"0x0D":0,"0x0E":0,"0x0F":0,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":0}}},{"setup":{"iram":{"0x08":255,"0x09":255,"0x0A":255,"0x0B":255,"0x0C":255,"0x0D":255,"0x0E":255,"0x0F":255,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":238}},"expect":{"iram":{"0x08":255,"0x09":255,"0x0A":255,"0x0B":255,"0x0C":255,"0x0D":255,"0x0E":255,"0x0F":255,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":248}}},{"setup":{"iram":{"0x08":128,"0x09":144,"0x0A":160,"0x0B":176,"0x0C":192,"0x0D":208,"0x0E":224,"0x0F":240,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":238}},"expect":{"iram":{"0x08":128,"0x09":144,"0x0A":160,"0x0B":176,"0x0C":192,"0x0D":208,"0x0E":224,"0x0F":240,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":192}}},{"setup":{"iram":{"0x08":0,"0x09":0,"0x0A":0,"0x0B":0,"0x0C":0,"0x0D":0,"0x0E":0,"0x0F":90,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":238}},"expect":{"iram":{"0x08":0,"0x09":0,"0x0A":0,"0x0B":0,"0x0C":0,"0x0D":0,"0x0E":0,"0x0F":90,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":90}}},{"setup":{"iram":{"0x08":55,"0x09":0,"0x0A":0,"0x0B":0,"0x0C":0,"0x0D":0,"0x0E":0,"0x0F":0,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":238}},"expect":{"iram":{"0x08":55,"0x09":0,"0x0A":0,"0x0B":0,"0x0C":0,"0x0D":0,"0x0E":0,"0x0F":0,"0x00":64,"0x01":65,"0x02":66,"0x03":67,"0x04":68,"0x05":69,"0x06":70,"0x07":71,"0x30":55}}}],"maxCyc":13,"maxBytes":15},"hints":["Mỗi lệnh ADD A,08H… dài 2 byte vì phải ghi địa chỉ. Lệnh nào cùng việc mà chỉ dài 1 byte?","Các ô 08H–0FH chính là R0–R7 của một băng thanh ghi. Băng nào?","Nếu các ô cần cộng là R0–R7 của băng đang chọn thì mỗi lệnh ADD chỉ còn 1 byte. Vòng lặp dùng @R0 ngắn hơn nữa, nhưng có kịp trong 13 chu kỳ không?"],"why":"ADD A,Rn mã hóa số thanh ghi vào 3 bit thấp của mã lệnh nên chỉ 1 byte, còn ADD A,direct cần thêm 1 byte địa chỉ. Chọn băng 1 (MOV PSW,#08H: 3 byte, 2 chu kỳ) biến 08H–0FH thành R0–R7: 3 + 1 + 7 + 2 + 2 = 15 byte, 2 + 1 + 7 + 1 + 2 = 13 chu kỳ. Code mẫu 20 byte, 11 chu kỳ: ít chu kỳ hơn nhưng dài hơn, một ví dụ đổi chu kỳ lấy byte."}]);

makeQuiz("quiz5","score5",[{"q": "Sau MOV PSW,#10H rồi MOV R3,#07H, giá trị 07H được ghi vào ô RAM nào?", "o": ["03H", "0BH", "1BH", "13H"], "a": 3, "e": "PSW = 10H nên RS1 RS0 = 10, chọn băng 2 (ô 10H–17H). R3 là ô 8 × 2 + 3 = 13H. 03H là R3 của băng 0 (quên đổi băng), 0BH là của băng 1."}, {"q": "Trình dịch kiểu Keil A51 dịch lệnh MOV A,R5 thành dãy byte nào?", "o": ["E5 05", "ED", "ED 05", "75 E0 05"], "a": 1, "e": "MOV A,Rn có mã E8H + n và không cần byte nào khác: R5 cho EDH, 1 byte. E5 05 là MOV A,05H (đọc ô 05H bằng địa chỉ, 2 byte), chỉ trùng kết quả khi đang ở băng 0."}, {"q": "Sau MOV A,#45H và ADD A,#3EH, các cờ CY, AC, OV, P bằng bao nhiêu?", "o": ["CY = 1, AC = 1, OV = 0, P = 1", "CY = 0, AC = 0, OV = 1, P = 0", "CY = 0, AC = 1, OV = 1, P = 1", "CY = 0, AC = 1, OV = 0, P = 1"], "a": 2, "e": "45H + 3EH = 83H: không nhớ ra khỏi bit 7 (CY = 0), 5H + EH > FH nên AC = 1, hai số dương ra kết quả âm nên OV = 1, 83H có ba bit 1 nên P = 1. Nhầm CY với OV là lỗi phổ biến nhất."}, {"q": "Ngay sau reset, chương trình chạy MOV A,#0AAH rồi PUSH ACC. Ô RAM nào bị ghi?", "o": ["Ô 08H, cũng là R0 của băng 1", "Ô 07H, cũng là R7 của băng 0", "Không ô nào, PUSH chỉ đổi SP", "Ô E0H, địa chỉ của ACC"], "a": 0, "e": "Sau reset SP = 07H. PUSH tăng SP trước rồi mới ghi, nên ghi vào ô 08H, trùng R0 của băng 1. Ô 07H chỉ là vị trí SP trỏ trước khi PUSH."}, {"q": "Lệnh nào dưới đây KHÔNG có trong tập lệnh 8051 (trình dịch báo lỗi)?", "o": ["MOV R1,A", "MOV A,R2", "MOV R1,R2", "MOV R1,02H"], "a": 2, "e": "8051 không có lệnh chép Rn sang Rn. MOV R1,A và MOV A,R2 là lệnh 1 byte; MOV R1,02H đọc ô 02H bằng địa chỉ trực tiếp (R2 của băng 0) và là cách sửa hợp lệ."}]);

